from collections import Counter
noise=[]
for r in range(27):
    for c in range(15):
        orth=[]
        for dr,dc in((-1,0),(1,0),(0,-1),(0,1)):
            rr,cc=r+dr,c+dc
            if 0<=rr<27 and 0<=cc<15: orth.append(g[rr][cc])
        cnt=Counter(orth)
        # cell is noise if its color not among orth neighbors? check all noise candidates
        if not any(v==g[r][c] for v in orth):
            top=cnt.most_common()
            noise.append((r,c,g[r][c],top))
for n in noise: print(n)

out=[row[:] for row in g]
for r,c,v,top in noise:
    cnt=dict(top); mx=max(cnt.values()); winners=[k for k,v2 in cnt.items() if v2==mx]
    if len(winners)==1: best=winners[0]
    else:
        nb=[w for w in winners if w!=3]
        best=nb[0] if nb else winners[0]
    out[r][c]=best
    if len(winners)>1: print('tie',(r,c),winners,'->',best)
print(out)
